css:
.fx-qz{width:min(620px,100%);border:1px solid var(--border);border-radius:var(--radius);padding:1.6em;background:var(--surface)}
.fx-qz .pr{height:.35em;border-radius:99px;background:var(--border);overflow:hidden;margin-bottom:1.4em}
.fx-qz .pr i{display:block;height:100%;width:0;background:var(--accent);transition:width calc(.4s/var(--speed))}
.fx-qz h3{font-size:1.5em;margin-bottom:1em}
.fx-qz .opts{display:grid;grid-template-columns:1fr 1fr;gap:.8em}
.fx-qz .opts button{text-align:left;padding:1.1em;border:1px solid var(--border);border-radius:var(--radius);background:none;color:var(--text);font:600 1em var(--font-body);cursor:pointer;display:grid;gap:.6em;transition:all calc(.2s/var(--speed))}
.fx-qz .opts button:hover{border-color:var(--primary);transform:translateY(-3px)}
.fx-qz .opts .fx-art{aspect-ratio:3/2;border-radius:calc(var(--radius)*.6)}
.fx-qz .res{text-align:center;padding:1em 0;animation:fx-qz-in calc(.5s/var(--speed)) both}
.fx-qz .res h3{font-size:2em;color:var(--primary);margin-bottom:.3em}
.fx-qz .res button{margin-top:1em;background:var(--primary);color:var(--on-primary);border:0;border-radius:99px;padding:.7em 1.4em;font:700 .95em var(--font-body);cursor:pointer}
@keyframes fx-qz-in{from{opacity:0;transform:translateY(12px)}}
@media(prefers-reduced-motion:reduce){.fx-qz .pr i,.fx-qz .opts button{transition:none}.fx-qz .res{animation:none}}
/* touch: :hover mirrored as .is-tap */
.fx-qz .opts button.is-tap{border-color:var(--primary);transform:translateY(-3px)}

